package com.autocare.platform.order;

import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.service.MerchantActor;
import java.math.*;
import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.web.server.ResponseStatusException;
import static com.autocare.platform.order.ReservationStore.*;

/** Read-only evidence aggregates. Never calls a channel, writes a ledger, or settles funds. */
public class BusinessDashboard {
 public static final String VERSION="R8B_BUSINESS_V1";
 private final ReservationStore db;private final OperatorIdentity operators;private final AssessmentFacts sources;
 private static final BigDecimal ZERO=new BigDecimal("0.00");
 public BusinessDashboard(ReservationStore db,OperatorIdentity operators,PlatformTransactionManager manager){this.db=db;this.operators=operators;sources=new AssessmentFacts(db,manager);}
 private static class Bucket {long count,unknown,excluded;BigDecimal amount=ZERO;}
 private static class Metric {
  final boolean money;long unclassified;final Map<String,Bucket> buckets=Map.of("formal",new Bucket(),"test",new Bucket());
  Metric(boolean money){this.money=money;}
  void known(String bucket,BigDecimal amount){if(bucket==null){unclassified++;return;}var b=buckets.get(bucket);b.count++;if(money)b.amount=b.amount.add(amount);}
  void unknown(String bucket){if(bucket==null)unclassified++;else buckets.get(bucket).unknown++;}
  void excluded(String bucket){if(bucket==null)unclassified++;else buckets.get(bucket).excluded++;}
  Map<String,Object> view(){var out=new LinkedHashMap<String,Object>();for(String k:List.of("formal","test")){var b=buckets.get(k);boolean known=b.unknown==0&&unclassified==0;var v=new LinkedHashMap<String,Object>();v.put("state",known?"KNOWN":"UNKNOWN");v.put("count",b.count);v.put("unknown_count",b.unknown);v.put("excluded_count",b.excluded);v.put("amount",money&&known?b.amount.setScale(2,RoundingMode.UNNECESSARY).toPlainString():null);out.put(k,v);}out.put("unclassified_count",unclassified);return out;}
 }
 private long n(Map<String,Object> r,String k){return r!=null&&r.get(k) instanceof Number v?v.longValue():0;}
 private boolean text(Object v){return v instanceof String s&&!s.isBlank();}
 private boolean moneyEquals(Object a,Object b){return a instanceof BigDecimal x&&b instanceof BigDecimal y&&x.compareTo(y)==0;}
 private boolean atMost(Object value,Instant end){return value!=null&&!instant(value).isAfter(end);}
 private String channel(Map<String,Object> p){return p==null?null:"WECHAT".equals(p.get("channel"))?"formal":"LOCAL_TEST".equals(p.get("channel"))?"test":null;}
 private String identity(long user){return switch(sources.identity(user)){case "VERIFIED_WECHAT"->"formal";case "TEST"->"test";default->null;};}
 private boolean payment(Map<String,Object> o,Map<String,Object> p,Instant now){return o!=null&&p!=null&&channel(p)!=null&&n(o,"is_deleted")==0&&n(p,"is_deleted")==0&&n(p,"order_id")==n(o,"id")&&"SUCCEEDED".equals(p.get("status"))&&"CNY".equals(p.get("currency"))&&p.get("amount") instanceof BigDecimal amount&&amount.signum()>0&&moneyEquals(amount,o.get("pay_amount"))&&text(p.get("payment_no"))&&text(p.get("channel_payment_no"))&&atMost(p.get("paid_at"),now)&&atMost(o.get("created_at"),instant(p.get("paid_at")))&&sources.count("SELECT COUNT(*) FROM payment WHERE order_id=? AND status='SUCCEEDED' AND is_deleted=0",o.get("id"))==1&&sources.count("SELECT COUNT(*) FROM payment_event WHERE payment_id=? AND channel=? AND outcome='PAID' AND event_hash<>'' AND is_deleted=0",p.get("id"),p.get("channel"))==1&&sources.count("SELECT COUNT(*) FROM payment_exception WHERE order_id=?",o.get("id"))==0;}
 private boolean refund(Map<String,Object> o,Map<String,Object> p,Map<String,Object> r,Instant now){return payment(o,p,now)&&r!=null&&n(r,"order_id")==n(o,"id")&&n(r,"payment_id")==n(p,"id")&&n(r,"is_deleted")==0&&"SUCCEEDED".equals(r.get("status"))&&"CNY".equals(r.get("currency"))&&moneyEquals(r.get("amount"),p.get("amount"))&&r.get("refund_no") instanceof String no&&no.matches("R[a-f0-9]{32}")&&text(r.get("channel_refund_no"))&&r.get("owner_consented_at")!=null&&r.get("merchant_consented_at")!=null&&refundSource(o,p,r,now)&&atMost(r.get("refunded_at"),now)&&atMost(p.get("paid_at"),instant(r.get("refunded_at")))&&atMost(r.get("owner_consented_at"),instant(r.get("refunded_at")))&&atMost(r.get("merchant_consented_at"),instant(r.get("refunded_at")))&&"CLOSED".equals(o.get("status"))&&"REFUND_CANCELLED".equals(o.get("close_reason"))&&sources.count("SELECT COUNT(*) FROM refund WHERE order_id=? AND status='SUCCEEDED' AND is_deleted=0",o.get("id"))==1&&sources.count("SELECT COUNT(*) FROM refund_event WHERE refund_id=? AND channel=? AND outcome='SUCCEEDED' AND event_hash<>'' AND is_deleted=0",r.get("id"),p.get("channel"))==1;}
 // Recorded completed-order returns need their original completion proof. This read path never enables a refund action.
 private boolean refundSource(Map<String,Object> o,Map<String,Object> p,Map<String,Object> r,Instant now){Object from=r.get("from_status");if(from==null)return false;if(OrderRefunds.ELIGIBLE.contains(from))return true;return "COMPLETED".equals(from)&&completion(o,p,sources.oneOrNull("SELECT * FROM order_redemption WHERE order_id=?",o.get("id")),now);}
 private boolean completion(Map<String,Object> o,Map<String,Object> p,Map<String,Object> r,Instant now){return payment(o,p,now)&&r!=null&&n(r,"merchant_id")==n(o,"merchant_id")&&n(r,"order_id")==n(o,"id")&&n(r,"payment_id")==n(p,"id")&&n(r,"test_mode")==("test".equals(channel(p))?1:0)&&atMost(r.get("redeemed_at"),now)&&atMost(p.get("paid_at"),instant(r.get("redeemed_at")))&&sources.count("SELECT COUNT(*) FROM order_status_transition WHERE order_id=? AND merchant_id=? AND actor_type='staff_account' AND actor_id=? AND from_status='PENDING_VERIFY' AND to_status='COMPLETED' AND action='ORDER_COMPLETE' AND occurred_at=?",o.get("id"),o.get("merchant_id"),r.get("staff_id"),r.get("redeemed_at"))==1;}
 private Map<String,Object> order(Object id){return sources.oneOrNull("SELECT * FROM `order` WHERE id=?",id);}
 private Map<String,Object> paymentRow(Object id){return sources.oneOrNull("SELECT * FROM payment WHERE id=?",id);}
 private Map<String,Object> fullRefund(Map<String,Object> o,Map<String,Object> p,Instant now){var rows=db.jdbc.queryForList("SELECT * FROM refund WHERE order_id=? AND status='SUCCEEDED'",o.get("id"));return rows.size()==1&&refund(o,p,rows.get(0),now)?rows.get(0):null;}
 private void payments(long shop,Instant start,Instant end,Instant now,Metric paid,Metric returned,Metric commission){
  for(var p:sources.rows("SELECT p.* FROM payment p JOIN `order` o ON o.id=p.order_id WHERE o.merchant_id=? AND p.status='SUCCEEDED' AND ((p.paid_at>=? AND p.paid_at<?) OR (p.paid_at IS NULL AND p.created_at<?)) ORDER BY p.id LIMIT 10001",shop,time(start),time(end),time(end))){var o=order(p.get("order_id"));if(payment(o,p,now))paid.known(channel(p),(BigDecimal)p.get("amount"));else paid.unknown(channel(p));}
  for(var r:sources.rows("SELECT r.* FROM refund r JOIN `order` o ON o.id=r.order_id WHERE o.merchant_id=? AND r.status='SUCCEEDED' AND ((r.refunded_at>=? AND r.refunded_at<?) OR (r.refunded_at IS NULL AND r.created_at<?)) ORDER BY r.id LIMIT 10001",shop,time(start),time(end),time(end))){var o=order(r.get("order_id"));var p=paymentRow(r.get("payment_id"));if(refund(o,p,r,now))returned.known(channel(p),(BigDecimal)r.get("amount"));else returned.unknown(channel(p));if(sources.count("SELECT COUNT(*) FROM merchant_commission_entry WHERE order_id=? AND event_key='REFUND'",r.get("order_id"))==0)commission.unknown(channel(p));}
 }
 private void orders(long shop,Instant start,Instant end,Instant now,Metric created,Metric completed,Metric coupons,Metric commission){
  for(var o:sources.rows("SELECT * FROM `order` WHERE merchant_id=? AND created_at>=? AND created_at<? ORDER BY id LIMIT 10001",shop,time(start),time(end))){String bucket=identity(n(o,"user_id"));if(n(o,"is_deleted")==0&&text(o.get("order_no"))&&n(o,"project_id")>0&&o.get("pay_amount") instanceof BigDecimal pay&&pay.signum()>0&&o.get("amount") instanceof BigDecimal amount&&amount.compareTo(pay)>=0)created.known(bucket,null);else created.unknown(bucket);}
  for(var r:sources.rows("SELECT * FROM order_redemption WHERE merchant_id=? AND redeemed_at>=? AND redeemed_at<? ORDER BY id LIMIT 10001",shop,time(start),time(end))){var o=order(r.get("order_id"));var p=paymentRow(r.get("payment_id"));String bucket=channel(p);boolean valid=o!=null&&n(o,"merchant_id")==shop&&completion(o,p,r,now);if(valid)completed.known(bucket,null);else completed.unknown(bucket);if(sources.count("SELECT COUNT(*) FROM merchant_commission_entry WHERE order_id=? AND event_key='COMPLETION'",r.get("order_id"))==0)commission.unknown(bucket);
   var allocation=sources.oneOrNull("SELECT * FROM order_coupon_allocation WHERE order_id=?",r.get("order_id"));if(allocation==null&&(o==null||o.get("coupon_id")==null))continue;
   if(!valid||allocation==null||!sources.cashSource(o,r,allocation)){coupons.unknown(bucket);continue;}var full=fullRefund(o,p,now);long refunds=sources.count("SELECT COUNT(*) FROM refund WHERE order_id=? AND status='SUCCEEDED'",o.get("id"));
   if(full!=null&&"RETURNED".equals(allocation.get("state"))&&sources.count("SELECT COUNT(*) FROM coupon_transaction_event WHERE kind='REFUND_RETURN' AND order_id=? AND refund_id=? AND user_coupon_id=? AND rule_version=?",o.get("id"),full.get("id"),allocation.get("user_coupon_id"),CouponTransactions.CASH_RULE)==1)coupons.excluded(bucket);else if(refunds==0&&"CONSUMED".equals(allocation.get("state")))coupons.known(bucket,null);else coupons.unknown(bucket);
  }
  for(var o:sources.rows("SELECT o.id,o.user_id,o.coupon_id FROM `order` o WHERE o.merchant_id=? AND NOT EXISTS(SELECT 1 FROM order_redemption r WHERE r.order_id=o.id) AND ((o.status='COMPLETED' AND o.created_at<?) OR EXISTS(SELECT 1 FROM order_status_transition t WHERE t.order_id=o.id AND t.to_status='COMPLETED' AND t.occurred_at>=? AND t.occurred_at<?)) ORDER BY o.id LIMIT 10001",shop,time(end),time(start),time(end))){String bucket=identity(n(o,"user_id"));completed.unknown(bucket);commission.unknown(bucket);if(o.get("coupon_id")!=null)coupons.unknown(bucket);}
 }
 private void services(long shop,Instant start,Instant end,Metric metric){for(var r:sources.rows("SELECT * FROM coupon_service_redemption WHERE merchant_id=? AND redeemed_at>=? AND redeemed_at<? ORDER BY id LIMIT 10001",shop,time(start),time(end))){String bucket=identity(n(r,"user_id"));boolean valid=false;try{var terms=db.parse(r.get("terms_json"));CouponInput.terms(terms);valid=CouponTransactions.SERVICE_RULE.equals(r.get("rule_version"))&&"SERVICE".equals(terms.path("type").asText())&&terms.path("project_id").asLong()==n(r,"project_id")&&moneyEquals(r.get("commission_amount"),ZERO)&&sources.publication(n(r,"user_id"),n(r,"user_coupon_id"),n(r,"coupon_id"),n(r,"publication_revision"),shop,r.get("redeemed_at"),terms)&&sources.count("SELECT COUNT(*) FROM coupon_transaction_event WHERE kind='SERVICE_REDEEM' AND redemption_id=? AND user_coupon_id=? AND rule_version=? AND before_status='AVAILABLE' AND after_status='USED'",r.get("id"),r.get("user_coupon_id"),CouponTransactions.SERVICE_RULE)==1;}catch(org.springframework.dao.DataAccessException e){throw e;}catch(RuntimeException invalid){}if(valid)metric.known(bucket,null);else metric.unknown(bucket);}}
 private void acquisitions(long shop,YearMonth month,Instant start,Instant end,Metric metric){var facts=new ArrayList<Map<String,Object>>();sources.acquisition(shop,month,start,end,facts);for(var f:facts){var source=sources.oneOrNull("SELECT user_id FROM invite_registration WHERE record_id=? AND merchant_id=?",f.get("source_id"),shop);String bucket=source==null?null:identity(n(source,"user_id"));switch(f.get("state").toString()){case "INCLUDED"->metric.known(bucket,null);case "EXCLUDED"->metric.excluded(bucket);default->metric.unknown(bucket);}}}
 private boolean commission(Map<String,Object> e,Instant now){
  var o=order(e.get("order_id"));var p=paymentRow(e.get("payment_id"));if(o==null||n(o,"merchant_id")!=n(e,"merchant_id")||!payment(o,p,now)||n(e,"test_mode")!=("test".equals(channel(p))?1:0)||!CommissionLedger.RULE.equals(e.get("rule_version"))||!"CNY".equals(e.get("currency"))||!(e.get("amount") instanceof BigDecimal)||!moneyEquals(e.get("base_amount"),o.get("pay_amount")))return false;
  if("WAIT_REVIEW".equals(e.get("kind")))return false;
  var snapshot=sources.oneOrNull("SELECT * FROM order_commission_snapshot WHERE order_id=?",o.get("id"));if(snapshot==null||n(snapshot,"merchant_id")!=n(o,"merchant_id")||!CommissionLedger.RULE.equals(snapshot.get("rule_version"))||!"CNY".equals(snapshot.get("currency"))||!moneyEquals(snapshot.get("base_amount"),o.get("pay_amount"))||!Objects.equals(iso(snapshot.get("booked_at")),iso(o.get("created_at"))))return false;
  if("REFUND_NO_CHARGE".equals(e.get("kind"))){var r=sources.oneOrNull("SELECT * FROM refund WHERE id=?",e.get("refund_id"));return "REFUND".equals(e.get("event_key"))&&refund(o,p,r,now)&&moneyEquals(e.get("amount"),ZERO)&&e.get("reference_entry_id")==null&&Objects.equals(iso(e.get("occurred_at")),iso(r.get("refunded_at")))&&sources.count("SELECT COUNT(*) FROM merchant_commission_entry WHERE order_id=? AND event_key='COMPLETION'",o.get("id"))==0&&sources.count("SELECT COUNT(*) FROM order_redemption WHERE order_id=?",o.get("id"))==0;}
  var policy=CommissionLedger.policy(db,n(o,"merchant_id"),instant(o.get("created_at")));if(policy==null||!"READY".equals(snapshot.get("state"))||n(snapshot,"policy_id")!=n(policy,"id")||!moneyEquals(snapshot.get("rate_percent"),CommissionLedger.RATE)||!moneyEquals(e.get("rate_percent"),snapshot.get("rate_percent"))||!Objects.equals(iso(snapshot.get("waived_until")),iso(policy.get("waived_until"))))return false;
  boolean waived=instant(snapshot.get("booked_at")).isBefore(instant(snapshot.get("waived_until")));BigDecimal expected=CommissionLedger.fee((BigDecimal)snapshot.get("base_amount"),waived);if(!moneyEquals(snapshot.get("commission_amount"),expected)||!(waived?"NEW_MERCHANT":"NONE").equals(snapshot.get("exemption"))||!Objects.equals(snapshot.get("exemption"),e.get("exemption")))return false;
  var completion=sources.oneOrNull("SELECT * FROM order_redemption WHERE order_id=?",o.get("id"));if(!completion(o,p,completion,now))return false;
  if("ACCRUAL".equals(e.get("kind")))return "COMPLETION".equals(e.get("event_key"))&&e.get("refund_id")==null&&e.get("reference_entry_id")==null&&Objects.equals(iso(e.get("occurred_at")),iso(completion.get("redeemed_at")))&&moneyEquals(e.get("amount"),expected);
  if(!"REFUND_REVERSAL".equals(e.get("kind"))||!"REFUND".equals(e.get("event_key")))return false;var r=sources.oneOrNull("SELECT * FROM refund WHERE id=?",e.get("refund_id"));var original=sources.oneOrNull("SELECT * FROM merchant_commission_entry WHERE id=? AND order_id=? AND merchant_id=? AND payment_id=? AND kind='ACCRUAL' AND event_key='COMPLETION'",e.get("reference_entry_id"),o.get("id"),o.get("merchant_id"),p.get("id"));return refund(o,p,r,now)&&original!=null&&commission(original,now)&&moneyEquals(e.get("amount"),expected.negate())&&Objects.equals(iso(e.get("occurred_at")),iso(r.get("refunded_at")));
 }
 private void commissions(long shop,Instant start,Instant end,Instant now,Metric metric){for(var e:sources.rows("SELECT * FROM merchant_commission_entry WHERE merchant_id=? AND occurred_at>=? AND occurred_at<? ORDER BY id LIMIT 10001",shop,time(start),time(end))){var p=paymentRow(e.get("payment_id"));if(commission(e,now))metric.known(channel(p),(BigDecimal)e.get("amount"));else metric.unknown(channel(p));}}
 private Map<String,Object> difference(Metric paid,Metric refunded){var out=new LinkedHashMap<String,Object>();for(String k:List.of("formal","test")){var p=paid.buckets.get(k);var r=refunded.buckets.get(k);boolean known=p.unknown==0&&r.unknown==0&&paid.unclassified==0&&refunded.unclassified==0;var v=new LinkedHashMap<String,Object>();v.put("state",known?"KNOWN":"UNKNOWN");v.put("amount",known?p.amount.subtract(r.amount).setScale(2,RoundingMode.UNNECESSARY).toPlainString():null);out.put(k,v);}return out;}
 private Map<String,Object> assessment(long shop,String month){var rows=db.jdbc.queryForList("SELECT id,revision,summary,captured_from,captured_to FROM assessment_snapshot WHERE merchant_id=? AND period_month=? ORDER BY revision DESC LIMIT 1",shop,month);if(rows.isEmpty())return null;var r=rows.get(0);var s=db.parse(r.get("summary"));var out=new LinkedHashMap<String,Object>();out.put("snapshot_id",r.get("id"));out.put("revision",r.get("revision"));out.put("state",s.path("state").asText());out.put("total_score",s.get("total_score"));out.put("grade",s.get("grade"));out.put("captured_from",iso(r.get("captured_from")));out.put("captured_to",iso(r.get("captured_to")));return out;}
 private Map<String,Object> dashboard(long shop,String text){var month=AssessmentCalculation.month(text);var merchant=db.one("SELECT id,name,address FROM merchant WHERE id=? AND status=1 AND is_deleted=0",shop);Instant now=db.now(),start=AssessmentCalculation.start(month),end=AssessmentCalculation.start(month.plusMonths(1));if(start.isAfter(now))throw new ResponseStatusException(HttpStatus.CONFLICT,"所选月份尚未开始");if(end.isAfter(now))end=now;
  var metrics=new LinkedHashMap<String,Metric>();for(String k:List.of("orders_created","payments","refunds","orders_completed","cash_coupon_uses","service_coupon_uses","new_customers","commission_accrual"))metrics.put(k,new Metric(Set.of("payments","refunds","commission_accrual").contains(k)));
  payments(shop,start,end,now,metrics.get("payments"),metrics.get("refunds"),metrics.get("commission_accrual"));orders(shop,start,end,now,metrics.get("orders_created"),metrics.get("orders_completed"),metrics.get("cash_coupon_uses"),metrics.get("commission_accrual"));services(shop,start,end,metrics.get("service_coupon_uses"));acquisitions(shop,month,start,end,metrics.get("new_customers"));commissions(shop,start,end,now,metrics.get("commission_accrual"));
  var out=new LinkedHashMap<String,Object>();out.put("merchant",Map.of("id",merchant.get("id"),"name",merchant.get("name"),"address",Objects.toString(merchant.get("address"),"")));out.put("period_month",text);out.put("timezone","Asia/Shanghai");out.put("window_from",start.toString());out.put("window_to",end.toString());out.put("observed_at",now.toString());out.put("currency","CNY");out.put("source_version",VERSION);var values=new LinkedHashMap<String,Object>();metrics.forEach((k,v)->values.put(k,v.view()));out.put("metrics",values);out.put("cash_difference",difference(metrics.get("payments"),metrics.get("refunds")));out.put("assessment",assessment(shop,text));return out;
 }
 public Map<String,Object> dashboard(OperatorActor a,long shop,String month){com.autocare.platform.service.ServiceCatalog.validateId(shop);AssessmentCalculation.month(month);return db.reads.execute(tx->{operators.authorize(a,OperatorIdentity.Permission.ANALYTICS,false);return dashboard(shop,month);});}
 public Map<String,Object> dashboard(MerchantActor a,String month){if(!a.manager())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"仅店长可读取本店经营看板");AssessmentCalculation.month(month);return db.reads.execute(tx->{db.merchant(a,false);return dashboard(a.merchantId(),month);});}
 public Map<String,Object> merchants(OperatorActor a,int page){if(page<1||page>1000000)throw ReservationInput.bad();return db.reads.execute(tx->{operators.authorize(a,OperatorIdentity.Permission.ANALYTICS,false);long count=db.jdbc.queryForObject("SELECT COUNT(*) FROM merchant WHERE status=1 AND is_deleted=0",Long.class);return page(db.jdbc.queryForList("SELECT id,name,COALESCE(address,'') AS address FROM merchant WHERE status=1 AND is_deleted=0 ORDER BY id DESC LIMIT 20 OFFSET ?",(page-1)*20L),count,page,20);});}
}
